// Normalizes the incoming form payload into a consistent record and
// applies spam / validation rules. Nothing here needs editing unless your
// form uses field names that are not in the lists below.
const cfg  = $('Workflow Configuration').first().json;
const raw  = $('Form Submission Trigger').first().json;
const body = raw.body || {};

const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const name     = pick('Name', 'name', 'fullName', 'full_name', 'your-name');
const email    = pick('Email', 'email', 'your-email').toLowerCase();
const phone    = pick('Phone', 'phone', 'tel', 'your-phone');
const message  = pick('Message', 'message', 'your-message', 'comments');
const source   = pick('Source', 'source', 'formName', 'form_name', 'page') || 'Website Contact Form';
// Hidden honeypot field: real users never fill it, bots usually do.
const honeypot = pick('website', 'company_url', '_honey', 'honeypot');

const now  = new Date();
const date = pick('Date', 'date') || now.toLocaleDateString('en-US');
const time = pick('Time', 'time') || now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

const emailOk   = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const linkCount = (message.match(/https?:\/\/|www\./gi) || []).length;
const maxLinks  = Number(cfg.maxLinksInMessage) || 3;

let rejectReason = '';
if (honeypot)                 rejectReason = 'Honeypot field was filled (likely bot)';
else if (!emailOk)            rejectReason = 'Invalid or missing email address';
else if (!message)            rejectReason = 'Empty message';
else if (linkCount > maxLinks) rejectReason = 'Too many links in message (' + linkCount + ')';

const headers = raw.headers || {};
const ip = headers['x-forwarded-for'] || headers['x-real-ip'] || '';

return [{ json: {
  name: name || '(not provided)',
  email,
  phone: phone || '(not provided)',
  message,
  date,
  time,
  source,
  ip,
  submittedAt: now.toISOString(),
  isValid: !rejectReason,
  rejectReason
} }];

